import type { VariableTypes } from './Variable'
import type { Role } from '../app'

/**
 * Configuration for a ServiceNow Variable Set (item_option_new_set)
 * Variable Sets are reusable collections of variables that can be attached to catalog items
 */
type VariableSetConfig<V extends VariableTypes = VariableTypes> = Now.Internal.WithIdAndMetadata<{
    /**
     * Display title of the variable set (translated field)
     */
    title: string

    /**
     * Optional : this is auto generated if not provided
     */
    internalName?: string

    /**
     * Optional name field
     */
    name?: string

    /**
     * Description of the variable set
     */
    description?: string

    /**
     * Type of variable set
     * - 'singleRow': Single Row (default)
     * - 'multiRow': Multi Row
     * @default 'singleRow'
     */
    type?: 'singleRow' | 'multiRow'

    /**
     * Layout style for the variable set
     * Common values: 'normal', '2down', '2across'
     * @default 'normal'
     */
    layout?: 'normal' | '2down' | '2across'

    /**
     * Display order of the variable set
     * @default 100
     */
    order?: number

    /**
     * Whether to display the title
     * @default false
     */
    displayTitle?: boolean

    /**
     * Set attributes (additional configuration)
     */
    setAttributes?: string

    /**
     * Version number of the variable set
     */
    version?: number

    /**
     * Roles that can read this variable set
     * An array of role names or Role references
     */
    readRoles?: (string | Role)[]

    /**
     * Roles that can write/modify this variable set
     * An array of role names or Role references
     */
    writeRoles?: (string | Role)[]

    /**
     * Roles that can create instances of this variable set
     * An array of role names or Role references
     */
    createRoles?: (string | Role)[]

    /** The variables for the variable set */
    variables?: V
}>

/**
 * Type alias for VariableSetConfig to allow using VariableSet as both a type and a function
 * @interface
 */
export type VariableSet<V extends VariableTypes = VariableTypes> = VariableSetConfig<V>

/**
 * Creates a Variable Set (`item_option_new_set`) — a reusable collection of variables that can
 * be attached to one or more catalog items.
 *
 * @param config Variable Set configuration — title, layout, variables, and role-based access.
 * @group ServiceCatalog
 */
// biome-ignore lint/suspicious/noRedeclare: function overloads require redeclaration
export function VariableSet<const V extends VariableTypes>(
    config: VariableSet<V> & { variables: V }
): VariableSet<V> & { variables: V }
// biome-ignore lint/suspicious/noRedeclare: function overloads require redeclaration
export function VariableSet(config: VariableSet): VariableSet
export function VariableSet(config: VariableSet) {
    return config
}
